// Mainteno Next — Color Wash branding injection
(function(){
  if(window.__maintenoColorWashBrandingLoaded)return;
  window.__maintenoColorWashBrandingLoaded=true;

  const LOGO = 'data:image/png;base64,';

  function ensureStyles(){
    if(document.getElementById('cwBrandingStyles'))return;
    const s=document.createElement('style');
    s.id='cwBrandingStyles';
    s.textContent=`
      .cwLoginBrand{display:flex;flex-direction:column;align-items:center;gap:10px;margin-bottom:14px}
      .cwLoginBrand img{width:min(220px,72%);height:auto;display:block}
      .cwLoginBrand .mut{text-align:center}

      .top .brand.cwBrandBar{display:flex;align-items:center;gap:10px;font-size:18px}
      .top .brand.cwBrandBar img{height:34px;width:auto;display:block;object-fit:contain;border-radius:6px;background:#fff;padding:2px}
      .top .brand.cwBrandBar .cwBrandText{display:flex;flex-direction:column;line-height:1.05}
      .top .brand.cwBrandBar .cwBrandText strong{font-size:18px;font-weight:900;color:#fff}
      .top .brand.cwBrandBar .cwBrandText small{font-size:10px;color:#bfdbfe}

      @media(max-width:640px){
        .top .brand.cwBrandBar img{height:28px}
        .top .brand.cwBrandBar .cwBrandText strong{font-size:15px}
        .cwLoginBrand img{width:min(180px,65%)}
      }
    `;
    document.head.appendChild(s);
  }

  function injectLoginLogo(){
    const loginCard=document.querySelector('.login .card');
    if(!loginCard)return;
    if(loginCard.querySelector('.cwLoginBrand'))return;

    const title=loginCard.querySelector('h1, h2, .title');
    const wrap=document.createElement('div');
    wrap.className='cwLoginBrand';
    wrap.innerHTML=`<img src="${LOGO}" alt="Color Wash logo"><div class="mut">Système de maintenance Color Wash</div>`;
    if(title) loginCard.insertBefore(wrap,title);
    else loginCard.prepend(wrap);
  }

  function injectTopBarLogo(){
    const brand=document.querySelector('.top .brand');
    if(!brand)return;
    if(brand.classList.contains('cwBrandBar'))return;

    brand.classList.add('cwBrandBar');
    brand.innerHTML=`<img src="${LOGO}" alt="Color Wash logo"><div class="cwBrandText"><strong>Color Wash</strong><small>Mainteno Next</small></div>`;
  }

  function applyBranding(){
    ensureStyles();
    injectLoginLogo();
    injectTopBarLogo();
  }

  const observer=new MutationObserver(()=>applyBranding());
  observer.observe(document.documentElement,{childList:true,subtree:true});

  document.addEventListener('DOMContentLoaded',applyBranding,{once:true});
  window.addEventListener('load',applyBranding,{once:true});
  setTimeout(applyBranding,0);
  setTimeout(applyBranding,300);
  setTimeout(applyBranding,1000);
})();
